package com.library.ui;
import com.library.dao.CategoryDAO; import com.library.model.*; import com.library.service.BookService; import javax.swing.*; import javax.swing.table.DefaultTableModel; import java.awt.*; import java.util.*;
public class BookManagementFrame extends JFrame { private final BookService service=new BookService();private final JTextField search=new JTextField(18),isbn=new JTextField(),name=new JTextField(),author=new JTextField(),publisher=new JTextField(),year=new JTextField(),quantity=new JTextField(),shelf=new JTextField();private final JComboBox<Category> category=new JComboBox<>();private final DefaultTableModel model=new DefaultTableModel(new String[]{"ID","ISBN","Name","Author","Category","Year","Qty","Available","Status"},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable table=new JTable(model);private long selectedId;
 public BookManagementFrame(){super("Book Management");setSize(1100,720);setMinimumSize(new Dimension(950,650));setLocationRelativeTo(null);setDefaultCloseOperation(DISPOSE_ON_CLOSE);for(Category c:new CategoryDAO().findAll())category.addItem(c);JPanel top=new JPanel(new BorderLayout());JPanel searchRow=new JPanel(new FlowLayout(FlowLayout.LEFT,10,10));searchRow.setBackground(Color.WHITE);searchRow.add(new JLabel("Search by title, author, ISBN or category"));search.setPreferredSize(new Dimension(320,34));searchRow.add(search);JButton find=UI.button("Search");find.addActionListener(e->load());searchRow.add(find);top.add(UI.header(this,"Book Management","Add, update, search and manage book inventory"),BorderLayout.NORTH);top.add(searchRow,BorderLayout.CENTER);add(top,BorderLayout.NORTH);UI.table(table);JScrollPane formScroll=new JScrollPane(form());formScroll.setPreferredSize(new Dimension(1,250));JSplitPane split=new JSplitPane(JSplitPane.VERTICAL_SPLIT,new JScrollPane(table),formScroll);split.setResizeWeight(.58);split.setDividerLocation(350);add(split,BorderLayout.CENTER);table.getSelectionModel().addListSelectionListener(e->select());load();}
 private JComponent form(){JPanel p=new JPanel(new GridLayout(0,4,12,8));p.setBackground(Color.WHITE);p.setBorder(BorderFactory.createTitledBorder(BorderFactory.createEmptyBorder(),"Book Details",0,0,new Font("Segoe UI",Font.BOLD,16),UI.NAVY));for(JComponent c:new JComponent[]{new JLabel("ISBN"),isbn,new JLabel("Book Name"),name,new JLabel("Author"),author,new JLabel("Category"),category,new JLabel("Publisher"),publisher,new JLabel("Publication Year"),year,new JLabel("Quantity"),quantity,new JLabel("Shelf Number"),shelf,button("Add Book",false),button("Update Selected",true),button("Deactivate",null)})p.add(c);return p;} private JButton button(String t,Boolean update){JButton b=UI.button(t);b.addActionListener(e->{try{if(update==null){if(selectedId==0)throw new IllegalArgumentException("Select a book first.");service.deactivate(selectedId);UI.info(this,"Book deactivated.");}else service.save(read(),update);load();clear();}catch(Exception x){UI.error(this,x);}});return b;}
 private Book read(){Book b=new Book();b.setBookId(selectedId);b.setIsbn(isbn.getText());b.setBookName(name.getText());b.setAuthor(author.getText());Category c=(Category)category.getSelectedItem();b.setCategoryId(c==null?0:c.getCategoryId());b.setPublisher(publisher.getText());b.setPublicationYear(Integer.parseInt(year.getText()));b.setQuantity(Integer.parseInt(quantity.getText()));b.setAvailableQuantity(selectedId==0?b.getQuantity():service.get(selectedId).getAvailableQuantity()+(b.getQuantity()-service.get(selectedId).getQuantity()));b.setShelfNumber(shelf.getText());return b;} private void load(){try{model.setRowCount(0);for(Book b:service.search(search.getText()))model.addRow(new Object[]{b.getBookId(),b.getIsbn(),b.getBookName(),b.getAuthor(),b.getCategoryName(),b.getPublicationYear(),b.getQuantity(),b.getAvailableQuantity(),b.getStatus()});}catch(Exception e){UI.error(this,e);}} private void select(){if(table.getSelectedRow()<0)return;selectedId=((Number)model.getValueAt(table.getSelectedRow(),0)).longValue();Book b=service.get(selectedId);isbn.setText(b.getIsbn());name.setText(b.getBookName());author.setText(b.getAuthor());publisher.setText(b.getPublisher());year.setText(String.valueOf(b.getPublicationYear()));quantity.setText(String.valueOf(b.getQuantity()));shelf.setText(b.getShelfNumber());for(int i=0;i<category.getItemCount();i++)if(category.getItemAt(i).getCategoryId()==b.getCategoryId())category.setSelectedIndex(i);} private void clear(){selectedId=0;table.clearSelection();for(JTextField f:new JTextField[]{isbn,name,author,publisher,year,quantity,shelf})f.setText("");} }
